167	
168	    private final OwnerMapper ownerMapper;
169	
170	    private final PetMapper petMapper;
171	
172	    private final VisitMapper visitMapper;
173	
174	    private final HttpServletRequest request;
175	
176	    /**
177	     * Remembers the owner produced by each previously seen {@code Idempotency-Key}, so a repeated
178	     * create with an already-seen key returns the originally created owner rather than a duplicate.
179	     */
180	    private final Map<String, OwnerDto> idempotencyStore = new ConcurrentHashMap<>();
