216	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
217	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
218	        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
