222	    /**
223	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
224	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
225	     * owner sign-ups.
226	     *
227	     * @param registrationDate the day to inspect, or {@code null}
228	     * @return {@code true} when more than the threshold of owners are registered on that day
229	     */
230	    private boolean isBulkSignupDay(LocalDate registrationDate) {
231	        return registrationDate != null
232	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
233	    }
234	
235	    /**
236	     * Determines whether the supplied city is approaching its per-city capacity, i.e. it currently
237	     * holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_LIMIT} minus one
238	     * owners (40-49). This flags a city nearing the hard limit of {@link #CITY_OWNER_LIMIT}; that hard
239	     * rejection is unchanged.
240	     *
241	     * @param city the city to inspect, or {@code null}
242	     * @return {@code true} when the city holds 40-49 owners
243	     */
244	    private boolean isApproachingCityCapacity(String city) {
245	        if (city == null) {
246	            return false;
247	        }
248	        long count = countOwnersInCity(city);
249	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
250	    }
251	
252	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
253	    @Override
254	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
255	        String idempotencyKey = idempotencyKey();
256	        if (idempotencyKey != null) {
257	            OwnerDto existing = this.idempotencyStore.get(idempotencyKey);
258	            if (existing != null) {
259	                return new ResponseEntity<>(existing, HttpStatus.OK);
260	            }
261	        }
262	        Owner owner = buildOwnerToCreate(ownerFieldsDto);
263	        boolean bulkSignupWarning = enforceCreateLimits(owner) > BULK_SIGNUP_WARNING_THRESHOLD;
264	        finalizeOwnerForCreate(owner);
265	        this.clinicService.saveOwner(owner);
266	        ResponseEntity<OwnerDto> response = createdOwnerResponse(owner, bulkSignupWarning);
267	        if (idempotencyKey != null) {
268	            this.idempotencyStore.put(idempotencyKey, response.getBody());
269	        }
270	        return response;
271	    }
272	
273	    /**
274	     * Returns the client-supplied {@code Idempotency-Key} for the current request, or {@code null}
275	     * when the header is absent or blank.
276	     */
277	    private String idempotencyKey() {
278	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
279	        return StringUtils.hasText(key) ? key : null;
280	    }
281	
282	    /**
283	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
284	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
285	     * submitted address is canonicalized, the required fields and the optional postcode and
286	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
287	     * registration date is defaulted to the server date when absent and rolled forward to a business
288	     * day. The household id and identity key are derived; a create whose identity key matches an
289	     * existing, non-deleted owner is rejected with a 409 unless it opts in with {@code sharesHousehold},
290	     * and otherwise a soft-match duplicate is flagged.
291	     *
292	     * @param ownerFieldsDto the submitted owner fields
293	     * @return the normalized owner, not yet persisted
294	     */
295	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
296	        resolveAddressFields(ownerFieldsDto);
297	        validateRequiredFields(ownerFieldsDto);
298	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
299	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
300	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
301	        owner.setEmail(normalizeEmail(owner.getEmail()));
302	        validateRegistrationDate(owner.getRegistrationDate());
303	        if (owner.getRegistrationDate() == null) {
304	            owner.setRegistrationDate(LocalDate.now());
305	        }
306	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
307	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
308	        resolveHouseholdIdentity(owner, sharesHousehold);
309	        return owner;
310	    }
311	
312	    /**
313	     * Places the owner about to be created into its household and settles its identity against the
314	     * owners already on file. The owner's {@code householdId} is still derived deterministically from
315	     * its last name and postcode (it drives the household size and membership-level cap), but identity
316	     * is now decided solely by the {@code identityKey}, the SHA-256 digest over the normalized
317	     * telephone, email and the last name's Soundex code. Unless the request opted into a shared
318	     * household, an owner whose identity key matches any existing, non-deleted owner is rejected with a
319	     * 409; and, again only when the household was not opted into, a soft-match against an existing owner
320	     * flags the new owner as a possible duplicate. Two owners sharing a last name and postcode but with
321	     * different telephones now derive different identity keys, so they are admitted (as a soft match)
322	     * rather than rejected, with their membership level later capped by
323	     * {@link #applyMembershipLevelCap(Owner)}.
324	     *
325	     * @param owner the normalized owner about to be created, with its contact details already normalized
326	     * @param sharesHousehold whether the request opted into joining an existing household
327	     */
328	    private void resolveHouseholdIdentity(Owner owner, boolean sharesHousehold) {
329	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
330	        owner.setIdentityKey(buildIdentityKey(owner));
331	        if (!sharesHousehold) {
332	            rejectDuplicateIdentity(owner);
333	        }
334	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
335	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
336	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
337	    }
338	
339	    /**
340	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
341	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
342	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
343	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
344	     * registration date, measured before it is saved, which the caller uses to decide the response's
345	     * {@code bulkSignupWarning}.
346	     *
347	     * @param owner the normalized owner about to be created
348	     * @return the number of owners already registered on the owner's registration date
349	     */
350	    private long enforceCreateLimits(Owner owner) {
351	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
352	            throw new OwnerCityFullException(owner.getCity());
353	        }
354	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
355	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
356	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
357	        }
358	        return ownersRegisteredOnDay;
359	    }
360	
361	    /**
362	     * Assigns the derived fields that only apply once the owner has cleared the create checks: its
363	     * de-duplicated member id, the number of existing namesakes, the household size once the
364	     * new owner is added, and the membership-level ceiling imposed by the household the owner joins.
365	     *
366	     * @param owner the normalized owner about to be created
367	     */
368	    private void finalizeOwnerForCreate(Owner owner) {
369	        owner.setMemberId(buildMemberId(owner));
370	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
371	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
372	        applyMembershipLevelCap(owner);
373	    }
374	
375	    /**
376	     * Caps the membership level of an owner about to be created so it cannot exceed one above the
377	     * current maximum membership level among the owner's existing household members. The owner is not
378	     * yet persisted, so {@link #activeHouseholdMembers(String)} returns exactly the members already on
379	     * file; each member's effective (already-capped) level is read via
380	     * {@link org.springframework.samples.petclinic.mapper.MembershipLevel#forOwner(Owner)}. When the
381	     * household has no existing member no ceiling applies and the cap is left unset, so the owner keeps
382	     * its fully-derived level.
383	     *
384	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
385	     */
386	    private void applyMembershipLevelCap(Owner owner) {
387	        activeHouseholdMembers(owner.getHouseholdId()).stream()
388	            .mapToInt(org.springframework.samples.petclinic.mapper.MembershipLevel::forOwner)
389	            .max()
390	            .ifPresent(maxLevel -> owner.setMembershipLevelCap(maxLevel + 1));
391	    }
392	
393	    /**
394	     * Builds the {@code 201 Created} response for a freshly persisted owner: maps it to a DTO, emits
395	     * the audit record, sets the {@code bulkSignupWarning} the caller computed from the pre-save daily
396	     * count, and adds the {@code Location} header pointing at the new owner.
397	     *
398	     * @param owner the owner that has just been saved, with its generated id populated
399	     * @param bulkSignupWarning whether the response should flag an unusually high same-day sign-up volume
400	     * @return the created-owner response
401	     */
402	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner, boolean bulkSignupWarning) {
403	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
404	        logOwnerCreated(owner, ownerDto);
405	        emitOwnerCreatedEvent(owner, ownerDto);
406	        enqueueWelcomeNotification(owner);
407	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
408	        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
409	        HttpHeaders headers = new HttpHeaders();
410	        headers.setLocation(UriComponentsBuilder.newInstance()
411	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
412	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
413	    }
414	
415	    /**
416	     * Emits the human-readable {@code OWNER_CREATED} audit line on the {@code AUDIT} logger, alongside
417	     * the structured event written by {@link #emitOwnerCreatedEvent}. The line records the owner's id,
418	     * member id, registration date and membership level. Kept as its own method so the response-builder
419	     * stays focused on assembling the response and the single audit-line format lives in one place.
420	     *
421	     * @param owner the owner that has just been saved, with its generated id populated
422	     * @param ownerDto the mapped DTO, source of the derived membership level
423	     */
424	    private void logOwnerCreated(Owner owner, OwnerDto ownerDto) {
425	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
426	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
427	            ownerDto.getMembershipLevel());
428	    }
429	
430	    /**
431	     * Emits the immutable, structured {@code OWNER_CREATED} audit event on the {@code AUDIT} logger,
432	     * alongside the human-readable audit line. The event is a JSON object
433	     * {@code {seq, ownerId, memberId, membershipLevel, event}} where {@code seq} is a
434	     * process-wide, monotonically increasing sequence across all creates. Its {@code memberId}
435	     * field carries the owner's primary identifier as returned by {@link #primaryIdentifier(Owner)}.
436	     *
437	     * @param owner the owner that has just been saved, with its generated id populated
438	     * @param ownerDto the mapped DTO, source of the derived membership level
439	     */
440	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
441	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(),
442	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel(), "OWNER_CREATED");
443	        try {
444	            AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
445	        }
446	        catch (JacksonException e) {
447	            AUDIT.warn("failed to serialize OWNER_CREATED audit event for owner id={}", owner.getId(), e);
448	        }
449	    }
450	
451	    /**
452	     * Enqueues the welcome notification for a freshly created owner by emitting a line on the
453	     * {@code NOTIFY} logger that carries the owner's id and member id. Kept as its own method, alongside
454	     * the audit emitters, so the response-builder stays focused on assembling the response and the
455	     * notification format lives in one place.
456	     *
457	     * @param owner the owner that has just been saved, with its generated id populated
458	     */
459	    private void enqueueWelcomeNotification(Owner owner) {
460	        NOTIFY.info("welcome notification enqueued for owner id={} memberId={}",
461	            owner.getId(), owner.getMemberId());
462	    }
463	
464	    /**
465	     * Returns the owner's primary identifier - the value the structured audit event carries as its
466	     * {@code memberId}. This is the owner's unified member id.
467	     *
468	     * @param owner the owner whose primary identifier is required
469	     * @return the owner's current primary identifier
470	     */
471	    private String primaryIdentifier(Owner owner) {
472	        return owner.getMemberId();
473	    }
474	
475	    /**
476	     * Immutable structured payload of an {@code OWNER_CREATED} audit event. The {@code memberId}
477	     * field holds the owner's primary identifier (see {@link #primaryIdentifier(Owner)}).
478	     */
479	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
480	        Integer membershipLevel, String event) {
481	    }
482	
483	    /**
484	     * Canonicalizes the submitted address fields into the form that is validated, stored and
485	     * returned, before any required-field check or mapping runs. This is the single place a create
486	     * request's address input is resolved.
487	     *
488	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
489	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
490	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
491	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
492	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
493	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
494	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
495	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
496	     * that is blank only after normalization is left blank here and rejected later by
497	     * {@link #validateRequiredFields}.
498	     *
499	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
500	     */
501	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
502	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
503	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
504	        if (!line1.isEmpty()) {
505	            ownerFieldsDto.setAddressLine1(line1);
506	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
507	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
508	        }
509	        else {
510	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
511	        }
512	    }
513	
514	    /**
515	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
516	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
517	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
518	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
519	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
520	     * normalization is still rejected.
521	     *
522	     * @param ownerFieldsDto the submitted owner fields
523	     */
524	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
525	        List<String> missingFields = new ArrayList<>();
526	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
527	            missingFields.add("firstName");
528	        }
529	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
530	            missingFields.add("lastName");
531	        }
532	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
533	            missingFields.add("address");
534	        }
535	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
536	            missingFields.add("city");
537	        }
538	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
539	            missingFields.add("telephone");
540	        }
541	        if (!missingFields.isEmpty()) {
542	            throw new MissingOwnerFieldsException(missingFields);
543	        }
544	    }
545	
546	    /**
547	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
548	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
549	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
550	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
551	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
552	     * whose {@code errors} array lists {@code postcode}.
553	     *
554	     * @param postcode the submitted postcode, or {@code null} when none was supplied
555	     * @param city the owner's city, whose region determines the acceptable postcode range
556	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
557	     */
558	    private void validatePostcode(String postcode, String city) {
559	        if (!StringUtils.hasText(postcode)) {
560	            return;
561	        }
562	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
563	            throw new InvalidOwnerFieldsException(List.of("postcode"));
564	        }
565	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
566	            throw new InvalidOwnerFieldsException(List.of("postcode"));
567	        }
568	    }
569	
570	    /**
571	     * Validates an owner's optional registration date. Registration date is optional, so a missing
572	     * value is accepted (the create later defaults it to the server date). When a value is supplied
573	     * it may not lie in the future: a date later than the server's current date is rejected with a
574	     * 400 whose {@code errors} array lists {@code registrationDate}.
575	     *
576	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
577	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
578	     */
579	    private void validateRegistrationDate(LocalDate registrationDate) {
580	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
581	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
582	        }
583	    }
584	
585	    /**
586	     * Rejects a submitted owner whose derived {@code identityKey} matches that of any existing,
587	     * non-deleted owner - the same normalized telephone, email and last-name Soundex, which marks the
588	     * same person being entered twice. This single identity key is the whole of duplicate detection:
589	     * because the telephone is part of the key, distinct people who merely share a last name and
590	     * postcode (but differ in telephone) derive a different key and so are admitted rather than
591	     * rejected. Soft-deleted owners are ignored, and the email-domain blocklist has already been
592	     * applied when the email was normalized. A genuine identity collision is reported to the client as
593	     * a 409 Conflict. A request may knowingly bypass this check by opting in with
594	     * {@code sharesHousehold}, in which case it is not performed.
595	     *
596	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
597	     */
598	    private void rejectDuplicateIdentity(Owner owner) {
599	        boolean identityInUse = this.clinicService.findAllOwners().stream()
600	            .filter(existing -> !existing.isDeleted())
601	            .anyMatch(existing -> owner.getIdentityKey().equals(existing.getIdentityKey()));
602	        if (identityInUse) {
603	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
604	        }
605	    }
606	
607	    /**
608	     * Returns the owners that currently belong to the household identified by {@code householdId} -
609	     * those sharing that derived id that have not been soft-deleted. Soft-deleted owners are excluded
610	     * because they no longer count as present members, so this is the household as it stands for the
611	     * owner being created. This is the single lookup of a household's current members behind the
612	     * household checks that reason about who is already there.
613	     *
614	     * @param householdId the derived household identifier to look up
615	     * @return the existing, non-deleted owners sharing that household, in no particular order
616	     */
617	    private List<Owner> activeHouseholdMembers(String householdId) {
618	        return this.clinicService.findAllOwners().stream()
619	            .filter(existing -> !existing.isDeleted())
620	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
621	            .collect(Collectors.toList());
622	    }
623	
624	    /**
625	     * Derives the owner's {@code identityKey} as the SHA-256 hex digest over
626	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the telephone
627	     * and email have already been normalized (the email lower-cased, or the empty string when none was
628	     * supplied) and the last name is reduced to its {@link Soundex} code. Because the normalized
629	     * telephone is part of the key, two owners who differ only in telephone derive different identity
630	     * keys, so they are not the same identity even when they share a household.
631	     *
632	     * @param owner the normalized owner about to be created, with its contact details already normalized
633	     * @return the derived identity key, as 64 lower-case hex characters
634	     */
635	    private String buildIdentityKey(Owner owner) {
636	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
637	        return Sha256.hex(owner.getTelephone() + "|" + email + "|" + Soundex.encode(owner.getLastName()));
638	    }
639	
640	    /**
641	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner whose
642	     * derived {@code identityKey} differs from an existing owner's - so it is not the same identity, and
643	     * not a 409 - yet shares that owner's last-name {@link Soundex} code and {@code postcode}. Such an
644	     * owner is still created, but is flagged as a possible duplicate of the matching owner. In
645	     * particular, two owners with the same last name and postcode but different telephones now derive
646	     * different identity keys, so instead of the old hard household-duplicate rejection they surface
647	     * here as a soft match. This is only consulted for owners that did not opt into a shared household:
648	     * an owner that declares {@code sharesHousehold} is a known household member, not a suspected
649	     * duplicate, so it is never flagged. The comparison only applies when a postcode was supplied, since
650	     * both owners must share one; when several existing owners match, the earliest (lowest id) is used.
651	     *
652	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
653	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
654	     */
655	    private Integer findPossibleDuplicate(Owner owner) {
656	        if (!StringUtils.hasText(owner.getPostcode())) {
657	            return null;
658	        }
659	        String soundex = Soundex.encode(owner.getLastName());
660	        return this.clinicService.findAllOwners().stream()
661	            .filter(existing -> !existing.isDeleted())
662	            .filter(existing -> !owner.getIdentityKey().equals(existing.getIdentityKey()))
663	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
664	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
665	            .map(Owner::getId)
666	            .filter(id -> id != null)
667	            .min(Integer::compareTo)
668	            .orElse(null);
669	    }
670	
671	    /**
672	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
673	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
674	     * address; the accepted value is lower-cased before it is stored and returned.
675	     *
676	     * @param email the raw email value submitted by the client, or {@code null}
677	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
678	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
679	     */
680	    private String normalizeEmail(String email) {
681	        if (!StringUtils.hasText(email)) {
682	            return email;
683	        }
684	        if (!EMAIL_PATTERN.matcher(email).matches()) {
685	            throw new InvalidOwnerFieldsException(List.of("email"));
686	        }
687	        String normalized = email.toLowerCase();
688	        String domain = normalized.substring(normalized.indexOf('@') + 1);
689	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
690	            throw new InvalidOwnerFieldsException(List.of("email"));
691	        }
692	        return normalized;
693	    }
694	
695	    /**
696	     * Assigns the owner's member id, formatted {@code <REGION><FY><HASH8><CHK>}. The region is derived
697	     * from the owner's postcode (falling back to its city), FY is the two-digit fiscal year of the
698	     * (business-day-adjusted) registration date, and the id itself - region, fiscal year, the hash of
699	     * the owner's normalized telephone and last name, and the trailing Luhn check digit - is composed
700	     * by {@link MemberId}. When the composed id collides with an existing owner's member id, it is
701	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of two or more that makes it
702	     * unique.
703	     *
704	     * @param owner the normalized owner about to be created
705	     * @return the assigned, de-duplicated member id
706	     */
707	    private String buildMemberId(Owner owner) {
708	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
709	        int fiscalYear = FiscalYear.twoDigit(owner.getRegistrationDate());
710	        String id = MemberId.forRegionYearAndIdentity(region, fiscalYear, owner.getTelephone(), owner.getLastName());
711	        return deduplicateMemberId(id);
712	    }
713	
714	    /**
715	     * De-duplicates a freshly composed member id against the ids of all existing owners. When the id is
716	     * already unique it is returned unchanged; otherwise {@code -<n>} is appended, using the smallest
717	     * {@code n} of two or more that yields an id no existing owner holds.
718	     *
719	     * @param id the composed member id, before de-duplication
720	     * @return the same id when unique, otherwise the id with the smallest available {@code -<n>} suffix
721	     */
722	    private String deduplicateMemberId(String id) {
723	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
724	            .map(Owner::getMemberId)
725	            .filter(existing -> existing != null)
726	            .collect(Collectors.toSet());
727	        if (!existingIds.contains(id)) {
728	            return id;
729	        }
730	        int suffix = 2;
731	        while (existingIds.contains(id + "-" + suffix)) {
732	            suffix++;
733	        }
734	        return id + "-" + suffix;
735	    }
736	
737	    /**
738	     * Counts how many owners already exist that share the supplied first and last name, compared
739	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
740	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
741	     *
742	     * @param firstName the submitted owner's first name
743	     * @param lastName the submitted owner's last name
744	     * @return the number of existing owners with the same first and last name, ignoring case
745	     */
746	    private int countNamesakes(String firstName, String lastName) {
747	        return (int) this.clinicService.findAllOwners().stream()
748	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
749	                && lastName.equalsIgnoreCase(existing.getLastName()))
750	            .count();
751	    }
752	
753	    /**
754	     * Counts how many existing owners already belong to the supplied household, identified by its
755	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
756	     * owner is added (this count plus one).
757	     *
758	     * @param householdId the normalized household identifier of the owner being created
759	     * @return the number of existing owners already sharing that {@code householdId}
760	     */
761	    private int countHouseholdMembers(String householdId) {
762	        return (int) this.clinicService.findAllOwners().stream()
763	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
764	            .count();
765	    }
766	
767	    /**
768	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
769	     * enforce the per-city capacity limit when a new owner is created.
770	     *
771	     * @param city the submitted owner's city
772	     * @return the number of existing owners in that city, ignoring case
773	     */
774	    private long countOwnersInCity(String city) {
775	        return this.clinicService.findAllOwners().stream()
776	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
777	            .count();
778	    }
779	
780	    /**
781	     * Counts how many owners have already been created on the supplied registration date. Used to
782	     * enforce the per-day capacity limit when a new owner is created.
783	     *
784	     * @param registrationDate the registration date of the owner being created
785	     * @return the number of existing owners already registered on that date
786	     */
787	    /**
788	     * Rolls a registration date forward to a business day. A registration date must fall on a
789	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
790	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
791	     * returned unchanged. Every value derived from the registration date (such as the member id's
792	     * fiscal-year segment) and the daily create-limit therefore use the adjusted date.
793	     *
794	     * @param date the effective registration date, whether supplied or defaulted to the server date
795	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
796	     */
797	    private LocalDate toBusinessDay(LocalDate date) {
798	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
799	            date = date.plusDays(1);
800	        }
801	        return date;
802	    }
803	
804	    private boolean isWeekend(LocalDate date) {
805	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
806	    }
807	
808	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
809	        return this.clinicService.findAllOwners().stream()
810	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
811	            .count();
812	    }
813	
814	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
815	    @Override
816	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
817	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
818	        if (currentOwner == null) {
819	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
820	        }
821	        currentOwner.setAddress(ownerFieldsDto.getAddress());
822	        currentOwner.setCity(ownerFieldsDto.getCity());
823	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
824	        currentOwner.setLastName(ownerFieldsDto.getLastName());
825	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
826	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
827	        this.clinicService.saveOwner(currentOwner);
828	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
829	    }
830	
831	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
832	    @Transactional
833	    @Override
834	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
835	        Owner owner = this.clinicService.findOwnerById(ownerId);
836	        if (owner == null) {
837	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
838	        }
839	        owner.setDeleted(true);
840	        this.clinicService.saveOwner(owner);
841	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
842	    }
843	
844	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
845	    @Override
846	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
847	        Owner owner = this.clinicService.findOwnerById(ownerId);
848	        if (owner == null) {
849	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
850	        }
851	        HttpHeaders headers = new HttpHeaders();
852	        Pet pet = petMapper.toPet(petFieldsDto);
853	        owner.setId(ownerId);
854	        pet.setOwner(owner);
855	        pet.getType().setName(null);
856	        this.clinicService.savePet(pet);
857	        PetDto petDto = petMapper.toPetDto(pet);
858	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
859	            .buildAndExpand(pet.getId()).toUri());
860	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
861	    }
862	
863	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
864	    @Override
865	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
866	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
867	        if (currentOwner != null) {
868	            Pet currentPet = this.clinicService.findPetById(petId);
869	            if (currentPet != null) {
870	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
871	                currentPet.setName(petFieldsDto.getName());
872	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
873	                this.clinicService.savePet(currentPet);
874	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
875	            }
876	        }
877	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
878	    }
879	
880	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
881	    @Override
882	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
883	        HttpHeaders headers = new HttpHeaders();
884	        Visit visit = visitMapper.toVisit(visitFieldsDto);
885	        Pet pet = new Pet();
886	        pet.setId(petId);
887	        visit.setPet(pet);
888	        this.clinicService.saveVisit(visit);
889	        VisitDto visitDto = visitMapper.toVisitDto(visit);
890	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
891	            .buildAndExpand(visit.getId()).toUri());
892	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
893	    }
894	
895	
896	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
897	    @Override
898	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
899	        Owner owner = this.clinicService.findOwnerById(ownerId);
900	        if (owner != null) {
901	            Pet pet = owner.getPet(petId);
902	            if (pet != null) {
903	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
904	            }
905	        }
906	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
907	    }
